INSERT INTO tariff_overlays (program, hts_pattern, country_scope, rate_pct, rate_type, legal_basis, effective_date, expiration_date, exclusions, stacking_rule, source_url, source_tier, last_updated, data_as_of)
SELECT 'sec301_china', code, 'CN', 7.5, 'ad_valorem', 'Section 301, China, List 4A: HTSUS heading 9903.88.15, U.S. note 20(s)(i) to subchapter III of chapter 99; 7.5% additional ad valorem since February 14, 2020 (HTS 2026 Rev. 23)', '2020-02-14', NULL, '["REVIEW: HTSUS U.S. notes 20(vvv) and 20(www) (headings 9903.88.69 and 9903.88.70, in effect) list USTR product exclusions by 10-digit statistical number under this 8-digit line, described by product. The exclusion depends on the product and the statistical suffix, which this app does not hold, so the duty cannot be stated without checking the notes."]', 'Additional to the HTS Column 1 rate (and any special rate); not reduced by FTA or USMCA claims; stacks with Section 232 and other duties. U.S. notes to subchapter III of chapter 99.', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev23&filename=Chapter%2099', 1, '2026-11-22', '2026-11-22' FROM c;
